INSERT INTO `products` (`id`, `title`, `description`, `price`, `original_price`, `category_id`, `stock`, `rating`, `review_count`, `image_url`, `badge`) VALUES
(1, 'Apple iPhone 15 Pro Max (256 GB) - Natural Titanium', 'Forged in titanium with A17 Pro chip, customizable Action button, 48MP main camera system with 5x Telephoto optical zoom, and Super Retina XDR display.', 149900.00, 159900.00, 1, 12, 4.90, 342, 'https://images.unsplash.com/photo-1695048133142-1a20484d2569?w=600&auto=format&fit=crop&q=80', 'Flipkart Choice'),
(2, 'Samsung Galaxy S24 Ultra 5G (Titanium Gray, 12GB, 512GB)', 'Galaxy AI is here. 200MP camera with AI Zoom, built-in S Pen, Snapdragon 8 Gen 3 for Galaxy, and quad HD+ Dynamic AMOLED 2X display.', 129999.00, 139999.00, 1, 15, 4.80, 289, 'https://images.unsplash.com/photo-1610945265064-0e34e5519bbf?w=600&auto=format&fit=crop&q=80', 'Amazon Bestseller'),
(3, 'OnePlus 12 5G (Silky Black, 16GB RAM, 512GB Storage)', 'Powered by Snapdragon 8 Gen 3, 4th Gen Hasselblad Camera System for Mobile, 120Hz ProXDR display with LTPO 3.0, and 100W SUPERVOOC fast charging.', 64999.00, 69999.00, 1, 20, 4.70, 198, 'https://images.unsplash.com/photo-1598327105666-5b89351aff97?w=600&auto=format&fit=crop&q=80', 'Top Rated'),
(4, 'Google Pixel 8 Pro (Obsidian, 12GB RAM, 128GB)', 'Google Tensor G3 chip, fully upgraded pro camera system with 5x telephoto, Best Take photo editing, and 24-hour battery life.', 88999.00, 106999.00, 1, 10, 4.70, 154, 'https://images.unsplash.com/photo-1598327105666-5b89351aff97?w=600&auto=format&fit=crop&q=80', 'AI Special'),
(5, 'Xiaomi Redmi Note 13 Pro+ 5G (Fusion Purple, 12GB, 512GB)', '200MP OIS camera, 3D Curved AMOLED 120Hz display, IP68 dust & water resistance, MediaTek Dimensity 7200-Ultra, and 120W HyperCharge.', 31999.00, 35999.00, 1, 25, 4.60, 420, 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=600&auto=format&fit=crop&q=80', 'Hot Deal'),
(6, 'Nothing Phone (2a) 5G (Black, 8GB RAM, 128GB Storage)', 'Unique transparent design with Glyph Interface lighting, custom Dimensity 7200 Pro 4nm processor, and dual 50MP rear camera setup.', 23999.00, 25999.00, 1, 30, 4.60, 512, 'https://images.unsplash.com/photo-1565849904461-04a58ad377e0?w=600&auto=format&fit=crop&q=80', 'Popular'),
(7, 'Vivo V30 Pro 5G (Andaman Blue, 12GB RAM, 512GB)', 'ZEISS Style Portrait quad 50MP camera system, Studio-Quality Aura Light portrait mode, 3D Curved 120Hz AMOLED screen, and MediaTek Dimensity 8200.', 46999.00, 51999.00, 1, 16, 4.60, 145, 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=600&auto=format&fit=crop&q=80', 'ZEISS Camera'),
(8, 'Realme GT 6 5G (Fluid Silver, 12GB RAM, 256GB Storage)', 'World\'s brightest 6000 nits Ultra Bright Display, Snapdragon 8s Gen 3 flagship processor, 50MP Sony LYT-808 OIS main camera, and 120W SuperVOOC charging.', 40999.00, 44999.00, 1, 18, 4.70, 165, 'https://images.unsplash.com/photo-1565849904461-04a58ad377e0?w=600&auto=format&fit=crop&q=80', 'Trending'),
(9, 'iQOO 12 5G (Alpha Black, 16GB RAM, 512GB Storage)', 'India\'s 1st Snapdragon 8 Gen 3 flagship mobile phone with Supercomputing Chip Q1, 144Hz AMOLED screen, and 50MP 3X Periscope Telephoto camera.', 57999.00, 64999.00, 1, 14, 4.80, 230, 'https://images.unsplash.com/photo-1598327105666-5b89351aff97?w=600&auto=format&fit=crop&q=80', 'Gaming Flagship'),
(10, 'POCO X6 Pro 5G (Racing Yellow, 12GB RAM, 512GB Storage)', 'MediaTek Dimensity 8300-Ultra flagship 4nm chipset, 1.5K 120Hz AMOLED display, 64MP OIS triple camera, and 67W Turbo Charge.', 24999.00, 28999.00, 1, 22, 4.50, 380, 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=600&auto=format&fit=crop&q=80', 'Value Beast'),
(11, 'U.S. Polo Assn. Men\'s Solid Cotton Casual Shirt (White)', 'Premium 100% breathable twill cotton casual button-down shirt with iconic embroidered brand logo, curved hemline, buttoned cuffs, and slim fit silhouette.', 1899.00, 2499.00, 2, 30, 4.60, 480, 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?w=600&auto=format&fit=crop&q=80', 'Flipkart Assured'),
(12, 'Raymond Men\'s Micro Check Formal Dress Shirt (Light Blue)', 'Crafted from fine Egyptian cotton yarns, featuring subtle micro-check patterns, stiff semi-cutaway formal collar, double-button cuffs, and crisp executive tailoring.', 2199.00, 2999.00, 2, 25, 4.70, 210, 'https://images.unsplash.com/photo-1596755094514-f87e34085b2c?w=600&auto=format&fit=crop&q=80', 'Executive Pick'),
(13, 'Tommy Hilfiger Men\'s Custom Fit Striped Casual Shirt (Navy)', 'Iconic American cool style featuring crisp vertical stripes, signature flag logo embroidery on chest pocket, and soft pre-shrunk oxford cotton fabric.', 3499.00, 4999.00, 2, 15, 4.80, 145, 'https://images.unsplash.com/photo-1603252109303-2751441dd157?w=600&auto=format&fit=crop&q=80', '30% OFF'),
(14, 'Mufti Men\'s Washed Indigo Denim Casual Shirt (Dark Blue)', 'Rugged yet stylish washed indigo denim shirt with double flap chest pockets, Western yoke stitching, snap-button closure, and comfortable regular fit.', 2299.00, 3199.00, 2, 20, 4.50, 190, 'https://images.unsplash.com/photo-1588359348347-9bc6cbaa689e?w=600&auto=format&fit=crop&q=80', 'Denim Classic'),
(15, 'Peter England Men\'s Non-Iron Formal Shirt (Pure White)', 'Innovated with patented crease-recovery technology, this non-iron formal shirt stays crisp all day long without needing ironing. Perfect for long office hours.', 1599.00, 1999.00, 2, 35, 4.60, 560, 'https://images.unsplash.com/photo-1602810318383-e386cc2a3ccf?w=600&auto=format&fit=crop&q=80', 'Non-Iron Tech'),
(16, 'Levi\'s Men\'s 511 Slim Fit Stretch Denim Jeans (Dark Wash)', 'Classic 5-pocket denim jeans crafted from stretch cotton fabric for flexibility, slim fit silhouette, zip fly, and signature leather patch on waist.', 2799.00, 3999.00, 2, 22, 4.50, 215, 'https://images.unsplash.com/photo-1542272604-780c36856842?w=600&auto=format&fit=crop&q=80', '30% OFF'),
(17, 'Allen Solly Men\'s Premium Cotton Polo T-Shirt (Navy Blue)', 'Soft breathable 100% combed cotton polo t-shirt with embroidered logo on chest, ribbed collar, and stylish contrast side slits.', 1199.00, 1699.00, 2, 40, 4.40, 310, 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=600&auto=format&fit=crop&q=80', 'Bestseller'),
(18, 'Nike Dri-FIT Men\'s Athletic Training Sportswear Tee (Black)', 'Engineered with sweat-wicking Dri-FIT fabric technology to keep you dry and comfortable during workouts, gym sessions, and casual sports.', 1795.00, 2295.00, 2, 28, 4.70, 340, 'https://images.unsplash.com/photo-1581655353564-df123a1eb820?w=600&auto=format&fit=crop&q=80', 'Nike Sport'),
(19, 'BIBA Women\'s Printed Anarkali Kurta & Dupatta Set (Royal Blue)', 'Elegant ethnic floral printed cotton Anarkali kurta set with flared hemline, V-neck, three-quarter sleeves, and matching printed dupatta.', 3499.00, 5999.00, 2, 15, 4.80, 95, 'https://images.unsplash.com/photo-1610030469983-98e550d6193c?w=600&auto=format&fit=crop&q=80', 'Festive Special'),
(20, 'Manyavar Men\'s Silk Blend Kurta & Churidar Set (Maroon)', 'Traditional maroon silk blend woven Jacquard design kurta paired with off-white churidar pajama, ideal for weddings, festivals, and ethnic ceremonies.', 4999.00, 6999.00, 2, 12, 4.90, 110, 'https://images.unsplash.com/photo-1583391733956-3750e0ff4e8b?w=600&auto=format&fit=crop&q=80', 'Wedding Wear'),
(21, 'Apple MacBook Air M3 Chip (15.3" Liquid Retina, 16GB, 512GB)', 'Incredibly thin and fast laptop powered by M3 chip, up to 18 hours battery life, 1080p FaceTime HD camera, and immersive 6-speaker sound system.', 134900.00, 144900.00, 3, 8, 4.90, 175, 'https://images.unsplash.com/photo-1517336714731-489689fd1ca8?w=600&auto=format&fit=crop&q=80', 'Apple M3'),
(22, 'ASUS ROG Zephyrus G16 OLED Gaming Laptop (Core Ultra 9, RTX 4070)', 'Ultra-sleek aluminum gaming laptop with 2.5K 240Hz ROG Nebula OLED display, Intel Core Ultra 9 185H, NVIDIA RTX 4070 8GB graphics, and 32GB LPDDR5X.', 189990.00, 209990.00, 3, 5, 4.80, 92, 'https://images.unsplash.com/photo-1603302576837-37561b2e2302?w=600&auto=format&fit=crop&q=80', 'OLED Gaming'),
(23, 'Apple iPad Air M2 Chip (11-inch, Wi-Fi, 256GB - Space Gray)', 'Redesigned iPad Air powered by M2 chip, Liquid Retina display with True Tone, landscape 12MP front camera, Wi-Fi 6E, and Apple Pencil Pro support.', 69900.00, 74900.00, 3, 14, 4.80, 210, 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=600&auto=format&fit=crop&q=80', 'M2 Power'),
(24, 'Sony BRAVIA 55-inch 4K Ultra HD Smart Google TV (KD-55X74L)', '4K Processor X1 delivering lifelike colors, Motionflow XR 100 for smooth action sequences, Dolby Audio, Open Baffle Speaker, and Google TV OS.', 54990.00, 77900.00, 3, 10, 4.70, 430, 'https://images.unsplash.com/photo-1593784991095-a205069470b6?w=600&auto=format&fit=crop&q=80', '29% OFF'),
(25, 'Samsung Galaxy Tab S9 Ultra (14.6" Dynamic AMOLED 2X, 12GB, 256GB)', 'Massive 14.6-inch Dynamic AMOLED 2X display with 120Hz refresh rate, bundled S Pen with ultra-low latency, IP68 water resistance, and Snapdragon 8 Gen 2.', 108999.00, 121999.00, 3, 7, 4.80, 88, 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=600&auto=format&fit=crop&q=80', 'Ultra Display'),
(26, 'Ergonomic Mechanical Keyboard', 'Compact 75% hot-swappable RGB mechanical keyboard with custom lubricated tactile switches and sound dampening foam layers.', 8999.00, 10999.00, 3, 8, 4.90, 210, 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=600&auto=format&fit=crop&q=80', 'Top Rated'),
(27, 'Sony WH-1000XM5 Wireless ANC Headphones (Silver/Black)', 'Industry-leading noise canceling headphones with two processors, 8 microphones for noise attenuation, crystal clear hands-free calling, and 30h battery life.', 29990.00, 34990.00, 4, 15, 4.90, 620, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&auto=format&fit=crop&q=80', 'Sony Flagship'),
(28, 'Apple AirPods Pro (2nd Gen) with MagSafe Case (USB-C)', 'Reengineered H2 chip powers up to 2x more Active Noise Cancellation, Transparency mode, Personalized Spatial Audio with dynamic head tracking, and USB-C case.', 22900.00, 24900.00, 4, 25, 4.80, 780, 'https://images.unsplash.com/photo-1600294037681-c80b4cb5b434?w=600&auto=format&fit=crop&q=80', 'Apple H2'),
(29, 'JBL Flip 6 Waterproof Portable Bluetooth Speaker (Squad/Black)', '2-way speaker system delivering loud, powerful, crystal clear sound with deep bass response, IP67 waterproof and dustproof design, and 12-hour playtime.', 9999.00, 13999.00, 4, 20, 4.70, 450, 'https://images.unsplash.com/photo-1608043152269-423dbba4e7e1?w=600&auto=format&fit=crop&q=80', 'JBL Original'),
(30, 'Aura ANC Wireless Headphones', 'Studio-quality wireless over-ear headphones with active noise cancellation, 40-hour battery life, and ultra-soft memory foam ear cushions.', 14999.00, 19999.00, 4, 14, 4.80, 142, 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&auto=format&fit=crop&q=80', 'Best Seller'),
(31, 'Puma Men\'s Smash v2 Leather Sneakers (White & Black)', 'Classic tennis-inspired low boot leather sneakers with comfortable SoftFoam+ sockliner, rubber outsole for traction, and iconic Puma formstrip.', 2999.00, 4999.00, 5, 18, 4.70, 180, 'https://images.unsplash.com/photo-1549298916-b41d501d3772?w=600&auto=format&fit=crop&q=80', '40% OFF'),
(32, 'HRX by Hrithik Roshan Men\'s Outdoor Running Shoes (Grey/Yellow)', 'Ultra-breathable mesh upper running shoes with responsive EVA midsole cushioning, TPU heel stabilizer, and anti-skid rubber outsole.', 1699.00, 3499.00, 5, 35, 4.50, 520, 'https://images.unsplash.com/photo-1542291026-7eec264c27ff?w=600&auto=format&fit=crop&q=80', '50% OFF'),
(33, 'Titan Neo Analog Black Dial Stainless Steel Watch for Men', 'Elegant stainless steel mesh strap watch featuring a minimalist black sunray dial, quartz movement, date window display, and 50m water resistance.', 3295.00, 4495.00, 5, 20, 4.60, 290, 'https://images.unsplash.com/photo-1523275335684-37898b6baf30?w=600&auto=format&fit=crop&q=80', 'Titan Trust'),
(34, 'Fire-Boltt Visionary 1.78" AMOLED Bluetooth Calling Smartwatch', 'Crisp 368x448 AMOLED display with Always-On screen, Bluetooth calling with built-in mic & speaker, 100+ sports modes, and SpO2 heart rate monitor.', 2499.00, 9999.00, 5, 45, 4.40, 890, 'https://images.unsplash.com/photo-1508685096489-7aacd43bd3b1?w=600&auto=format&fit=crop&q=80', '75% OFF'),
(35, 'Philips Digital Air Fryer HD9252/90 with Rapid Air Technology', 'Fry, bake, grill, roast, and reheat with up to 90% less fat. Features 7 touch screen presets, patented starfish bottom design, and easy cleanup.', 7999.00, 11995.00, 6, 16, 4.70, 670, 'https://images.unsplash.com/photo-1585515320310-259814833e62?w=600&auto=format&fit=crop&q=80', 'Healthy Cooking'),
(36, 'Nordic Handcrafted Ceramic Coffee Mug Set (Set of 4)', 'Handcrafted matte finish ceramic coffee mugs designed with Scandinavian minimalist lines, 350ml capacity, and ergonomic heat-insulated handles.', 1299.00, 1999.00, 6, 25, 4.60, 140, 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600&auto=format&fit=crop&q=80', 'Crafted Ceramic')
